def rules_for(path: str) -> list[tuple[str, str]]:
    import fnmatch

    rules = list(EXACT.get(path, []))
    for pattern, extra in GLOB:
        if fnmatch.fnmatch(path, pattern):
            rules.extend(extra)
    return [(r, w) for r, w in rules if w]
